    if (str == null) {
        return suffix == null;
    }
    if (suffix == null) {
        return false;
    }
    int sLen = suffix.length();
    int tLen = str.length();
    if (sLen > tLen) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, tLen - sLen, suffix, 0, sLen);
    } else {
        return str.endsWith(suffix);
    }
}

